        Console.WriteLine($"PASS: {test.Description}");
    }
    else
    {
        // Format expected/got to avoid long floating point precision artifacts in output
        Console.WriteLine($"FAIL: {test.Description} (expected: {test.Expected:F2}, got: {actual:F2})");
    }
}
